xpath.script:
                (function () {
                    if (window.location.pathname.indexOf('/shop/address') === -1) { return; }
                    var waitingForToast = false;
                    // Mark when the user clicks the address "Siguiente" button (several possible selectors)
                    $(document).on('click', 'form#checkout_address_form button[type=submit], form[action*="/shop/checkout"] button[type=submit], button.o_wsale_checkout_next', function () {
                        waitingForToast = true;
                    });
                    // When an ajax call finishes after that click, show the toast once
                    $(document).ajaxSuccess(function (event, xhr, settings) {
                        if (!waitingForToast) { return; }
                        waitingForToast = false;
                        var $toast = $('
Aguarda un momento mientras cargamos los datos de matriculación. ¡Gracias!');
                        $('body').append($toast);
                        setTimeout(function () { $toast.fadeOut(300, function () { $(this).remove(); }); }, 5000);
                    });
                })();
